*{box-sizing:border-box}body{margin:0;background:transparent;color:#20222b;font:13px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,select{font:inherit}button{cursor:pointer}button:focus-visible,select:focus-visible{outline:2px solid #426cff;outline-offset:2px}#tool-status{display:none}.toc-panel{margin-inline:8px;padding:12px;border:1px solid #e9e9ef;border-radius:12px;background:#fff;min-width:0}.toc-head{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px}.toc-title{font-size:12px;color:#727685;font-weight:650;letter-spacing:.045em}.toc-modes{display:flex;align-items:center;gap:1px;padding:2px;border:1px solid #e9e9ef;border-radius:8px;background:#fafafd}.toc-modes button{display:grid;place-items:center;width:27px;height:27px;padding:0;border:0;border-radius:5px;background:transparent;color:#858996}.toc-modes button svg{width:14px;height:14px}.toc-modes button[aria-pressed=true]{background:#fff;color:#303342;box-shadow:0 1px 3px #171d2a15}.toc-source{width:100%;margin:0 0 7px;padding:5px;border:1px solid #e9e9ef;border-radius:6px;color:inherit;background:transparent;font-size:12px}.toc-scroll{max-height:540px;overflow:auto;scrollbar-width:thin;overscroll-behavior:contain}.toc-list{display:grid;gap:1px;list-style:none;margin:0;padding:0}.toc-list li{padding-left:calc(var(--depth,0)*12px);min-width:0}.toc-list li.toc-answer-start{border-top:1px solid #e9e9ef;margin-top:7px;padding-top:7px}.toc-link{display:block;width:100%;text-align:left;border:0;border-left:2px solid transparent;padding:2px 0 2px 10px;background:transparent;color:#6b7280;border-radius:0 3px 3px 0;font-size:13px;line-height:1.45}.toc-link.child{font-size:12px}.toc-link:hover,.toc-link[aria-current=location]{color:#20222b}.toc-link[aria-current=location]{border-left-color:#426cff}.toc-link span{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;overflow-wrap:anywhere;max-height:2.9em}.toc-empty,.toc-error{font-size:12px;margin:7px 0 0;color:#777b8a}.toc-error{color:#b04c59}.toc-more{display:block;width:100%;margin-top:6px;padding:7px 8px;text-align:left;border:1px solid #e9e9ef;border-radius:7px;background:#f8f9fc;color:#5062a0;font-size:12px}.toc-more:hover{background:#eef2ff;color:#2c49b6}.toc-more[hidden]{display:none}@media(prefers-color-scheme:dark){body{color:#e6e8ef}.toc-panel{background:#1b1c24;border-color:#383a48}.toc-title{color:#a4a7b3}.toc-modes{background:#16171e;border-color:#383a48}.toc-modes button{color:#8b90a1}.toc-modes button[aria-pressed=true]{background:#2a2d3a;color:#e3e7f4}.toc-source{border-color:#383a48}.toc-link{color:#a0a5b4}.toc-link:hover,.toc-link[aria-current=location]{color:#f4f5f7}.toc-list li.toc-answer-start{border-color:#383a48}.toc-more{background:#272936;color:#acbfff;border-color:#383a48}.toc-more:hover{background:#303850;color:#d4dfff}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

/* R4.8: refresh is an action, separate from the three view modes. */
.toc-actions{display:flex;align-items:center;gap:6px}
.toc-refresh{display:grid;place-items:center;width:29px;height:29px;padding:0;flex:none;border:1px solid #e9e9ef;border-radius:8px;background:#fff;color:#727685}
.toc-refresh:hover{background:#f5f7fc;color:#303342}
.toc-refresh svg{width:15px;height:15px}
.toc-refresh[aria-busy=true] svg{animation:toc-spin .9s linear infinite}
@keyframes toc-spin{to{transform:rotate(360deg)}}
.toc-link:disabled{cursor:default;opacity:.55}
.toc-error[data-state=loading]{color:#777b8a}
@media(prefers-color-scheme:dark){.toc-refresh{background:#1b1c24;border-color:#383a48;color:#a4a7b3}.toc-refresh:hover{background:#292c38;color:#f4f5f7}}
@media(prefers-reduced-motion:reduce){.toc-refresh[aria-busy=true] svg{animation:none}}

/* R1.8: approved fourth Side Panel view, existing free TOC rows unchanged. */
[hidden]{display:none!important}
.toc-head{gap:6px;min-width:0;white-space:nowrap}
.toc-title{flex:0 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;font-size:11px;letter-spacing:.07em}
.toc-actions{flex:none;min-width:0}
.toc-modes{flex:none}
.toc-modes button{flex:none}
.toc-modes button:hover{background:#ecf1fa;color:#365eda}
.toc-modes button[aria-pressed=true]{color:#365eda}
.toc-ai-view{min-width:0}
.toc-member-card{min-width:0;padding:12px;background:#f8faff;border:1px solid #e4eaf7;border-radius:9px}
.toc-member-head,.toc-member-bottom,.toc-promo-head{display:flex;justify-content:space-between;align-items:baseline;gap:6px;min-width:0}
.toc-member-title{font-size:13px;font-weight:680;line-height:1.4;color:#1b2c49}
.toc-member-tag{font-size:10px;color:#7283a0;white-space:nowrap}
.toc-member-description{margin:6px 0 10px;color:#566982;font-size:12px;line-height:1.55}
.toc-member-bottom{align-items:center;flex-wrap:wrap;gap:8px}
.toc-member-meta{font-size:11px;color:#697b96;line-height:1.4}
.toc-member-entry{min-height:30px;padding:5px 10px;border:1px solid #365eda;border-radius:7px;background:#365eda;color:#fff;font-size:12px}
.toc-member-disclaimer{margin:7px 0 0;color:#8b96a8;text-align:right;font-size:10px}
.toc-promo{margin-top:10px;min-width:0;padding:10px 12px;background:#fff;border:1px solid #e6ebf3;border-radius:9px}
.toc-promo-brand,.toc-promo-kind{font-size:10px;line-height:1.4;color:#8290a5}
.toc-promo-kind{flex:none}
.toc-promo-title{margin:5px 0 0;font-size:12px;font-weight:650;line-height:1.45;color:#2c3b56}
.toc-promo-description{margin:3px 0 0;color:#6d7f95;font-size:11px;line-height:1.55}
.toc-promo-action{margin-top:6px;padding:3px 0;border:0;background:transparent;color:#365eda;font-size:11px;text-align:left}
.toc-ai-status{margin:12px 1px 1px;color:#53647e;font-size:11px;line-height:1.5}
@media(prefers-color-scheme:dark){
.toc-modes button:hover{background:#303850;color:#c7d6ff}
.toc-modes button[aria-pressed=true]{color:#c7d6ff}
.toc-member-card{background:#23283a;border-color:#39415d}
.toc-member-title,.toc-promo-title{color:#edf1fc}
.toc-member-description,.toc-member-meta,.toc-ai-status{color:#abb8d0}
.toc-member-tag,.toc-member-disclaimer,.toc-promo-brand,.toc-promo-kind,.toc-promo-description{color:#9aa8be}
.toc-promo{background:#1b1c24;border-color:#383a48}
}

/* R1.8.1: keep 200% zoomed narrow toolbars inside their own scroll area. */
.toc-actions{flex:0 1 auto;margin-left:auto;min-width:0;overflow-x:auto;overscroll-behavior-x:contain;scrollbar-width:none}
.toc-actions::-webkit-scrollbar{display:none}

.toc-settings{font-size:12px;color:inherit}
.toc-settings fieldset{min-width:0;margin:0;padding:8px 0;border:0}
.toc-settings fieldset+fieldset{margin-top:12px;border-top:1px solid #e9e9ef;padding-top:12px}
.toc-settings legend{padding:0;color:#727685;font-size:11px;font-weight:600}
.toc-settings label{display:flex;align-items:center;gap:12px;min-height:38px;cursor:pointer}
.toc-settings [data-setting-label]{order:-1;flex:1;overflow-wrap:anywhere}
.toc-settings input{appearance:none;flex:none;position:relative;width:30px;height:18px;margin:0;border:1px solid #cbd0d9;border-radius:10px;background:#e9ecf1;cursor:pointer}
.toc-settings input::before{content:"";position:absolute;left:2px;top:2px;width:12px;height:12px;border-radius:50%;background:#fff;box-shadow:0 1px 2px #171d2a26}
.toc-settings input:checked{background:#426cff;border-color:#426cff}
.toc-settings input:checked::before{left:14px}
.toc-settings input:disabled{opacity:.5;cursor:wait}
.toc-settings input:focus-visible{outline:2px solid #426cff;outline-offset:3px}
.toc-settings label:has(input:focus-visible){border-radius:5px;background:#f5f7fc}
@media(prefers-color-scheme:dark){.toc-settings fieldset+fieldset{border-color:#383a48}.toc-settings legend{color:#a4a7b3}.toc-settings input{background:#383a48;border-color:#606575}.toc-settings input:checked{background:#426cff;border-color:#426cff}.toc-settings label:has(input:focus-visible){background:#292c38}}

